entries[1218305] = { ["name"] = "Void-Forged Stallion", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Forged just as their shoes once were, these beasts are less horses now and void energy in their likeness.\"\nDrop:\nZone:\nVision of Stormwind (Revisited)" }
entries[1218306] = { ["name"] = "Void-Scarred Pack Mother", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Fighting her corrupted handlers this pack mother freed herself and her pups. However, freedom from their handlers did not free them from the void in this lost place. She taught her pups to be even more dangerous beasts, and they now stalk throughout Orgrimmar fetching her food as all compete to survive.\"\nDrop:\nZone:\nVision of Orgrimmar (Revisited)" }
entries[1218307] = { ["name"] = "Void-Scarred Windrider", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"When the void energies were released, it drove most windriders feral. They killed each other and their trainers. The gates to their roost were locked by the survivors. Some surviving windriders can still be seen gliding above, but none dare return to their new deadly domain to see what remains.\"\nDrop:\nZone:\nVision of Orgrimmar (Revisited)" }
entries[1218308] = { ["name"] = "Enkindling Inferno", ["text"] = "Instant\nBlazikon unleashes a fiery burst towards each extinguished candle, reigniting that candle and inflicting 8487876 Fire damage to all players in its path.\n\nThe inferno sears all players, inflicting 242445 Fire damage every 1 sec for 8 sec. This effect stacks." }
